mapper.select:
SELECT ODATE, OSTATUS, MNO
  FROM ORDERS
 WHERE ONO = #{ono}

mapper.update:
UPDATE ORDERS
   SET OSTATUS = 'REFUND_PENDING'
 WHERE MNO = #{mno}
   AND ONO = #{ono}
   AND OSTATUS = 'PAID'

UPDATE ORDERS
   SET OSTATUS = 'PAID'
 WHERE MNO = #{mno}
   AND ONO = #{ono}
   AND OSTATUS = 'REFUND_PENDING'

UPDATE ORDERS
   SET OSTATUS = 'REFUND'
 WHERE MNO = #{mno}
   AND ONO = #{ono}
   AND OSTATUS = 'REFUND_PENDING'
